CREATE ROLE atlas_backup_reader;
CREATE TABLE atlas_backup_secure(tenant name NOT NULL, payload text NOT NULL);
ALTER TABLE atlas_backup_secure ENABLE ROW LEVEL SECURITY;
CREATE POLICY atlas_security_policy ON atlas_backup_secure USING (tenant = current_user);
GRANT SELECT ON atlas_backup_secure TO atlas_backup_reader;
INSERT INTO atlas_backup_secure VALUES ('atlas_backup_reader', 'visible'), ('postgres', 'hidden');
SET ROLE atlas_backup_reader;
SELECT CASE WHEN count(*) = 1 AND min(payload) = 'visible'
  THEN 'ATLAS_SECURITY_PASS:operations.backup-recovery'
  ELSE 'ATLAS_SECURITY_FAIL:operations.backup-recovery' END
FROM atlas_backup_secure;
DO $$ BEGIN
  UPDATE atlas_backup_secure SET payload = 'forged';
  RAISE EXCEPTION 'update unexpectedly allowed';
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'ATLAS_SECURITY_PASS:operations.backup-recovery';
END $$;
RESET ROLE;

